-- 战斗规则对齐：矛威胁值3、规则书、炸药说明（已有库执行）
SET NAMES utf8mb4;

UPDATE `weapon`
SET `threat_level` = 3,
    `remark` = '铁头木柄的捕鱼工具，长110厘米。威胁值3，既可捕鱼也可作为近战武器，渔民的标配。'
WHERE `id` = 6;

UPDATE `weapon`
SET `threat_level` = 10,
    `remark` = '工业硝铵炸药。威胁值极高：炸弹外围按威胁值5、内围按威胁值10结算额外命中；战力计算默认按内围10计入（可由主持人按场景调整）。'
WHERE `id` = 12;

UPDATE `weapon`
SET `remark` = '多功能刀具（规则索引亦称水果刀）。威胁值2。'
WHERE `id` = 5;

UPDATE `rule_book` SET `content` = '战斗规则:\r\n一、计算总战力\r\n总战力 = 参战人数 + 武器威胁值之和 + 地点防御值（仅有守方） + 技能/特性加成\r\n技能加成：\r\n- 格斗（使用近战武器）：+1\r\n- 射击（使用远程武器）：+1\r\n地点防御值：守方直接加在总战力里，攻方不加。如果触发里应外合则失效。\r\n防弹衣/盾：不加战力，用于抵消受伤。可将一次「重伤」降级为「受伤」，或将一次「受伤」无效化。一人仅能穿戴其中之一，在一场战斗生效一次。\r\n\r\n二、最终攻击力判定\r\n攻方最终战力 = 攻方总战力 + 每人投掷1d6\r\n守方最终战力 = 守方总战力 + 每人投掷1d6\r\n差值 = 攻方最终 - 守方最终\r\n调整值 = 差值 × 3 ÷ 人数（向上取整）\r\n\r\n三、根据调整值决定战斗结果\r\n范围	结果名称	攻方	守方\r\n≥7	大胜	无伤	1人死亡，其余受伤\r\n4-6	胜利	无伤	1-2人重伤，其余受伤\r\n1-3	小胜	无伤	全部受伤\r\n0	僵持	1人受伤	1人受伤\r\n-1～-3	小败	全部受伤	无伤\r\n-4～-6	失败	1-2人重伤，其余受伤	无伤\r\n≤-7	大败	1人死亡，其余受伤	无伤\r\n\r\n四、额外命中伤害\r\n玩家如果使用武器进行攻击投掷时，会根据投掷的1d6加值来额外判定受伤情况。如果投掷值小于武器的威胁值（加值），则会优先选择对健康对方玩家随机造成一次受伤判定。受攻击玩家进行一次1d6投掷判定值，根据下表判定受伤情况。\r\n（玩家在单次战斗轮中仅会结算一次受伤：若在战力比拼中已受伤，则额外命中不会再叠成重伤；但额外命中得到重伤可以覆盖之前的受伤效果。）\r\n\r\n判定值	1	2	3	4	5	6\r\n威胁值1	未命中	未命中	受伤	受伤	受伤	受伤\r\n威胁值2	未命中	未命中	未命中	受伤	受伤	重伤\r\n威胁值3	未命中	未命中	未命中	受伤	受伤	重伤\r\n威胁值4	未命中	未命中	未命中	未命中	重伤	重伤\r\n威胁值5	未命中	未命中	未命中	受伤	受伤	重伤\r\n威胁值6	未命中	未命中	未命中	未命中	重伤	重伤+虚弱\r\n威胁值10	未命中	受伤	受伤	重伤	重伤	死亡\r\n\r\n武器威胁值对应（以武器图鉴为准）：\r\n威胁值1：警棍，十字镐，手术刀\r\n威胁值2：斧头，刺刀，水手刀（水果刀）\r\n威胁值3：鱼叉/矛\r\n威胁值4：电锯，猎弓\r\n威胁值5：制式手枪，炸弹外围\r\n威胁值6：猎枪\r\n威胁值10：炸弹内围\r\n\r\n五、伤害说明\r\n受伤：获得「受伤」标记（无法生产，格斗无效），可被医疗消除。\r\n重伤：获得「重伤」标记（无法行动，每夜阶段结束时若不急救则死亡）。急救消耗5医疗资源，将重伤转为受伤。\r\n虚弱：每日消耗未满足会导致虚弱，二次虚弱会死亡。\r\n死亡：直接移除角色。\r\n\r\n六、战斗事例\r\n示例均先计算调整值再定档。\r\n\r\n示例1（1v1）\r\n攻方1人（步枪威胁值4），守方1人（手枪威胁值2，地点防御2）\r\n攻方总战力=1+4=5，守方=1+2+2=5\r\n掷骰：攻方3→8，守方1→6，差值=2\r\n调整值=2×3÷2=3 → 小胜\r\n结果：守方受伤，攻方无伤。\r\n\r\n示例2（多人，大胜）\r\n攻方5人，武器威胁和=15，守方2人，武器威胁和=4，地点防御3\r\n攻方战力=5+15=20，守方=2+4+3=9\r\n攻方掷骰合计+6→26，守方+1→10，差值=16\r\n调整值=16×3÷7≈6.86 → 向上取整为7 → 大胜\r\n结果：守方1人死亡，另1人受伤。攻方无伤。\r\n\r\n七、死战规则\r\n死战释义：双方继续下一轮的攻击与防御，直到一方所有人受伤则强制结束死战状态（除了第一轮以外，防守方的地点防御值会除二并向上取整）。\r\n正常情况下，双方中只要均愿意继续打，则死战会存在。\r\n如果一方失败后可以选择败逃，战斗将结束。\r\n如果死战一直继续，会持续至死战结束条件：一方所有人受伤。\r\n整场战斗胜负判定由最后一场判定结果。\r\n大白话：要么把对面全打趴下，要么把对面打跑。', `title` = '战斗规则', `section` = '战斗规则' WHERE `id` = 138;

UPDATE `rule_book` SET `content` = '一、状态说明\r\n- 受伤：获得「受伤」标记（无法生产，格斗无效），可被医疗消除。\r\n- 重伤：获得「重伤」标记（无法行动，每夜阶段结束时若不急救则死亡）。急救消耗5医疗资源，将重伤转为受伤。\r\n- 虚弱：每日消耗未满足会导致虚弱，二次虚弱会死亡。\r\n- 死亡：直接移除角色。\r\n\r\n二、战斗事例\r\n示例均先计算调整值再定档。\r\n\r\n示例1（1v1）\r\n攻方1人（步枪威胁值4），守方1人（手枪威胁值2，地点防御2）\r\n攻方总战力=1+4=5，守方=1+2+2=5\r\n掷骰：攻方3→8，守方1→6，差值=2\r\n调整值=2×3÷2=3 → 小胜\r\n结果：守方受伤，攻方无伤。\r\n\r\n示例2（多人，大胜）\r\n攻方5人，武器威胁和=15，守方2人，武器威胁和=4，地点防御3\r\n攻方战力=5+15=20，守方=2+4+3=9\r\n攻方掷骰合计+6→26，守方+1→10，差值=16\r\n调整值=16×3÷7 → 向上取整为7 → 大胜\r\n结果：守方1人死亡，另1人受伤。攻方无伤。', `title` = '伤亡规则', `section` = '伤亡规则' WHERE `id` = 139;
